              line(70, -40, 70, -230, 26, "rgba(214,168,255,0.6)"); line(70, -40, 70, -230, 8, "rgba(255,255,255,0.95)");
              line(-220, -230, -220, 10, 26, "rgba(214,168,255,0.6)"); line(-220, -230, -220, 10, 8, "rgba(255,255,255,0.95)");
              ctx.restore();
